describe('User Profile - Connect Google Account', () => {
    beforeEach(() => {
        cy.visit('/user-profile');
        cy.login(); // Assuming there's a custom command for login
    });

    it('should successfully connect Google account', () => {
        cy.get('button[data-testid="connect-google"]').click();
        cy.url().should('include', 'google.com');

        // Simulate Google login
        cy.get('input[type="email"]').type('user@example.com');
        cy.get('button[type="submit"]').click();
        cy.get('input[type="password"]').type('password123');
        cy.get('button[type="submit"]').click();

        // After successful login, redirect back to the app
        cy.url().should('include', '/user-profile');
        cy.get('.connected-accounts').should('contain', 'Google Account Connected');
    });

    it('should handle Google account connection failure', () => {
        cy.get('button[data-testid="connect-google"]').click();
        cy.url().should('include', 'google.com');

        // Simulate Google login with incorrect credentials
        cy.get('input[type="email"]').type('user@example.com');
        cy.get('button[type="submit"]').click();
        cy.get('input[type="password"]').type('wrongpassword');
        cy.get('button[type="submit"]').click();

        // Expect an error message
        cy.get('.error-message').should('contain', 'Invalid credentials');
        cy.url().should('include', 'google.com'); // Should remain on Google login page
    });
});
